// Generated by tools/symmetry/color-table.py from the pinned py4DSTEM automatic plan sectors.
// Inverse-transpose sector matrices are pinned to avoid platform-dependent inversion at runtime.
import Foundation
import simd
import DiffractoCore

extension CrystalOrientationSymmetry {
    internal var py4DSTEMBasis: [SIMD3<Double>] {
        switch laueClass {
        case .oneBar: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(0.0,1.0,0.0),
            SIMD3(1.0,0.0,0.0),
        ]
        case .twoOverM: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(0.0,1.0,0.0),
            SIMD3(1.0,0.0,0.0),
        ]
        case .mmm: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(1.0,0.0,0.0),
            SIMD3(0.0,1.0,0.0),
        ]
        case .fourOverM: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(1.0,0.0,0.0),
            SIMD3(0.0,1.0,0.0),
        ]
        case .fourOverMmm: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(1.0,-1.0,0.0),
            SIMD3(0.0,1.4142135623730951,0.0),
        ]
        case .threeBar: return [
            SIMD3(-7.070501591499379e-17,0.0,1.0),
            SIMD3(0.5773502691896257,-1.0000000000000002,0.0),
            SIMD3(0.5773502691896257,1.0000000000000002,0.0),
        ]
        case .threeBarM: return [
            SIMD3(-7.070501591499379e-17,0.0,1.0),
            SIMD3(0.5773502691896257,-1.0000000000000002,0.0),
            SIMD3(0.5773502691896257,1.0000000000000002,0.0),
        ]
        case .sixOverM: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(1.0,-0.5773502691896258,0.0),
            SIMD3(0.0,1.1547005383792515,0.0),
        ]
        case .sixOverMmm: return [
            SIMD3(0.0,0.0,1.0),
            SIMD3(0.0,1.9999999999999996,0.0),
            SIMD3(1.0,-1.732050807568877,0.0),
        ]
        case .mThreeBar: return [
            SIMD3(0.0,-1.0,1.0),
            SIMD3(1.0,-1.0,0.0),
            SIMD3(0.0,1.732050807568877,0.0),
        ]
        case .mThreeBarM: return [
            SIMD3(0.0,-1.0,1.0),
            SIMD3(-1.414213562373095,1.4142135623730951,0.0),
            SIMD3(1.732050807568877,0.0,0.0),
        ]
        }
    }

    internal func py4DSTEMColor(_ d: SIMD3<Double>) -> SIMD3<Float> {
        func clip(_ x: Double) -> Double { min(1,max(0,x)) }
        let rgb: SIMD3<Double>
        if laueClass == .twoOverM {
            // The 2/m "half" sector is [001],[010],[100]. NNLS of [A,-A] splits
            // the Cartesian components into positive/negative parts; no iterative solve is needed.
            let x = clip(d.x), nx = clip(-d.x), y = clip(abs(d.y)), z = clip(abs(d.z))
            rgb = [z+nx, z+y*0.3+x*0.7, z+y]
        } else {
            let a = py4DSTEMBasis
            var weights = a.map { clip(($0.x*d.x).addingProduct($0.y,d.y).addingProduct($0.z,d.z)) }
            let maximum = weights.max()!
            if maximum > 0 { weights = weights.map { $0/maximum } }
            rgb = [weights[0], weights[1]*0.7+weights[2]*0.3, weights[2]]
        }
        return SIMD3(Float(clip(rgb.x)),Float(clip(rgb.y)),Float(clip(rgb.z)))
    }
}
